13	use IEEE.NUMERIC_STD.ALL;
14	use std.textio.all;
15	use ieee.std_logic_textio.all;
16	
17	entity sim_sharp is
18	end sim_sharp;
19	
20	architecture sim of sim_sharp is
21	
22	-- define constants for simulation
23	  constant stimuli_filename  : string  := "Lindau_Harbour_720p.ppm";
24	  constant expected_filename : string  := "Lindau_Harbour_expected.ppm";
25	  constant response_filename : string  := "Lindau_Harbour_response.ppm";
26	  constant x_blank           : integer := 100;   -- horizontal blanking
27	  constant trail             : integer := 1000;  -- clock cycles after active image
28	
29	-- signals of testbench
30	  signal clk       : std_logic := '0';
31	  signal reset_n   : std_logic;
32	  signal enable_in : std_logic_vector(2 downto 0);
33	  signal vs_in     : std_logic;
34	  signal hs_in     : std_logic;
35	  signal de_in     : std_logic;
36	  signal r_in      : std_logic_vector(7 downto 0);
37	  signal g_in      : std_logic_vector(7 downto 0);
38	  signal b_in      : std_logic_vector(7 downto 0);
39	  signal vs_out    : std_logic;
40	  signal hs_out    : std_logic;
41	  signal de_out    : std_logic;
42	  signal r_out     : std_logic_vector(7 downto 0);
43	  signal g_out     : std_logic_vector(7 downto 0);
44	  signal b_out     : std_logic_vector(7 downto 0);
45	  signal clk_o     : std_logic;
46	  signal led       : std_logic_vector(2 downto 0);
47	  signal x_size, y_size      : integer;
48	  signal end_tb    : integer   := 0;
49	  signal mismatch  : integer   := 0;
50	
51	begin
52	
53	  -- clock generation
54	  clk <= not clk after 5 ns;
55	
56	  -- instantiation of design-under-verification
57	  duv : entity work.sharp
58	    port map (clk       => clk,
59	              reset_n   => reset_n,
60	              enable_in => enable_in,
61	              vs_in     => vs_in,
62	              hs_in     => hs_in,
63	              de_in     => de_in,
64	              r_in      => r_in,
65	              g_in      => g_in,
66	              b_in      => b_in,
67	              vs_out    => vs_out,
68	              hs_out    => hs_out,
69	              de_out    => de_out,
70	              r_out     => r_out,
71	              g_out     => g_out,
72	              b_out     => b_out,
73	              clk_o     => clk_o,
74	              led       => led);
75	
76	  -- main process for stimuli
77	  stimuli_process : process
78	
79	  -- variables for stimuli file
80	    file stimuli_file       : text;
81	    variable l              : line;
82	    variable stimuli_status : file_open_status;
83	    variable x, y      : integer;
84	    variable i, r_integer, g_integer, b_integer  : integer;
85	
86	  begin
87	
88	    -- read stimuli file
89	    file_open(stimuli_status, stimuli_file, stimuli_filename, read_mode);
90	    readline(stimuli_file, l);          -- read line 1 with magic number
91	    readline(stimuli_file, l);          -- read line 2 with comments
92	    readline(stimuli_file, l);          -- read line 3 with x, y size
93	    read(l, i); x_size <= i;
94	    read(l, i); y_size <= i;
95	    readline(stimuli_file, l);          -- read line 4 with maximum value
96	    readline(stimuli_file, l);          -- read first line of image data
97	
