function status = write_ascii_ppm(img, file_name)
%
% write image as an ascii ppm-file
%
% FPGA Vision Remote Lab http://h-brs.de/fpga-vision-lab
% (c) Marco Winzker, Hochschule Bonn-Rhein-Sieg, 14.01.2020

